class Solution {
    public int findContentChildren(int[] g, int[] s) {
        boolean[] used = new boolean[s.length];
        int content = 0;
        for (int child : g) {
            int bestIdx = -1;
            for (int j = 0; j < s.length; j++) {
                if (!used[j] && s[j] >= child) {
                    if (bestIdx == -1 || s[j] < s[bestIdx]) {
                        bestIdx = j;
                    }
                }
            }
            if (bestIdx != -1) {
                used[bestIdx] = true;
                content++;
            }
        }
        return content;
    }
}

