        int chooseA = Integer.MAX_VALUE, chooseB = Integer.MAX_VALUE;
        if (a < n) chooseA = costs[idx][0] + dfs(costs, idx + 1, a + 1, b, n);
        if (b < n) chooseB = costs[idx][1] + dfs(costs, idx + 1, a, b + 1, n);
        return Math.min(chooseA, chooseB);
    }
}

