class Solution:
    def checkValidString(self, s: str) -> bool:
        def dfs(i, open_cnt):
            if open_cnt < 0: return False
            if i == len(s): return open_cnt == 0
            if s[i] == '(': return dfs(i + 1, open_cnt + 1)
            if s[i] == ')': return dfs(i + 1, open_cnt - 1)
            return dfs(i + 1, open_cnt + 1) or dfs(i + 1, open_cnt - 1) or dfs(i + 1, open_cnt)
        return dfs(0, 0)

